var i=`0487-sfouf`;var o=`world-0487`;var a=`LB`;var t=`western-asia`;var r=8;var l=48;var s={en:`Sfouf`,ua:`Сфуф`};var g={en:`A traditional dish from Lebanon, centered on semolina flour, all-purpose flour, baking powder, whole cow milk. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ліван. Основні складники: семоліна, пшеничне борошно універсальне, розпушувач тіста, цільне коров'яче молоко. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`semolina-flour`,280,`g`],[`all-purpose-flour`,90,`g`],[`white-granulated-sugar`,170,`g`],[`ground-turmeric`,6,`g`],[`baking-powder`,10,`g`],[`whole-cow-milk`,250,`ml`],[`sunflower-oil`,70,`ml`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:6,i:[[`tahini`,25,`g`],[`pine-nut`,65,`g`]]},{en:`Bake in a preheated 180°C oven for about 35 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 35 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:35,i:[]}];var d={slug:i,id:o,country:`LB`,region:t,servings:8,minutes:48,title:s,text:g,steps:u};export{a as country,d as default,o as id,l as minutes,t as region,r as servings,i as slug,u as steps,g as text,s as title};